+    toast.setWrapText(true);
+
+    // Root actuel (BorderPane) → on l’attrape via la scene
+    var sceneRoot = grid.getScene().getRoot();
+
+    // On superpose via StackPane temporaire
+    if (sceneRoot instanceof StackPane sp) {
+        // si déjà StackPane, parfait
+        sp.getChildren().add(toast);
+        StackPane.setAlignment(toast, Pos.BOTTOM_CENTER);
+    } else {
+        // sinon on remplace le root par un StackPane qui contient l'ancien root + le toast
+        StackPane wrapper = new StackPane(sceneRoot, toast);
+        StackPane.setAlignment(toast, Pos.BOTTOM_CENTER);
+        grid.getScene().setRoot(wrapper);
+    }
+
+    PauseTransition pause = new PauseTransition(Duration.seconds(2.0));
+    pause.setOnFinished(ev -> {
+        var rootNow = grid.getScene().getRoot();
+        if (rootNow instanceof StackPane sp2) {
+            sp2.getChildren().remove(toast);
+        }
+    });
+    pause.play();
